// Disposable native design prototype. Does not read libraries, connect to hosts, or modify media.
import AppKit
import SwiftUI

struct Sample: Identifiable {
  let id: Int; let name: String; let size: String; var paired = false; var favorite = false; var video = false
}
let samples = [Sample(id:0,name:"Sea pavilion.png",size:"4.2 MB",paired:true,favorite:true),Sample(id:1,name:"Travertine steps.jpg",size:"5.1 MB"),Sample(id:2,name:"Dunes at dawn.png",size:"3.8 MB",paired:true),Sample(id:3,name:"Coast walk.mov",size:"38.6 MB",video:true),Sample(id:4,name:"Afternoon room.png",size:"4.6 MB",paired:true),Sample(id:5,name:"Olive shadows.jpg",size:"2.9 MB",favorite:true),Sample(id:6,name:"Blue hour.jpg",size:"6.8 MB"),Sample(id:7,name:"Limestone light.jpg",size:"4.3 MB"),Sample(id:8,name:"Forest path.mp4",size:"21.4 MB",video:true)]
final class DesignState: ObservableObject {
  @Published var grid = true
  @Published var scenario = "Browse"
  @Published var selected: Set<Int> = [0]
  @Published var active: Int? = 0
  @Published var showRail = true
  @Published var thumbnail = 130.0
  @Published var previewHeight = 378.0
  @Published var detailsWidth = 282.0
  @Published var gridPreviewWidth = 480.0
  @Published var gridImageHeight = 360.0
  @Published var folder: String? = nil
  @Published var archived: Set<Int> = []
  @Published var showArchive = false
  @Published var favorites = false
  @Published var notice: String?
  var remote: Bool { scenario == "Remote" }
  var shown: [Sample] { samples.filter { (showArchive ? archived.contains($0.id) : !archived.contains($0.id)) && (!favorites || $0.favorite) && (folder == nil || (folder == "Architecture" ? [0,1,4,7].contains($0.id) : [2,3,5,6,8].contains($0.id))) } }
  var current: Sample? { samples.first { $0.id == active } }
  func setScenario(_ name: String) { scenario=name; selected=[0]; active=0; archived=[]; showArchive=false; favorites=false; folder=nil; notice=nil; if name == "Batch" { selected=[0,1,2] }; if name == "Archive" {archived=[0,2]; showArchive=true}; if name == "First remote use" || name == "Start" {selected=[];active=nil} }
  func openChild(_ name:String?) {scenario="Browse";folder=name;showArchive=false;favorites=false;active=shown.first?.id;selected=Set(shown.first.map{[$0.id]} ?? [])}
  func select(_ id: Int) { if NSEvent.modifierFlags.contains(.command) {if selected.contains(id) {selected.remove(id)} else {selected.insert(id)};active=selected.contains(id) ? id : selected.sorted().last } else if NSEvent.modifierFlags.contains(.shift),let anchor=selected.sorted().first {selected=Set(min(anchor,id)...max(anchor,id));active=id} else {selected=[id];active=id} }
}
enum Palette {
  static func adaptive(_ light: UInt32,_ dark: UInt32)->Color {Color(nsColor:NSColor(name:nil,dynamicProvider:{appearance in let v=appearance.bestMatch(from:[.darkAqua,.aqua]) == .darkAqua ? dark:light;return NSColor(srgbRed:Double((v>>16)&255)/255,green:Double((v>>8)&255)/255,blue:Double(v&255)/255,alpha:1)}))}
  static let onAccent=adaptive(0xffffff,0x1b271b)
  static let paper=adaptive(0xfafaf8,0x202222),chrome=adaptive(0xf1f2ef,0x282a29),rail=adaptive(0xeeefeb,0x252725),stage=adaptive(0xe9eae6,0x171918),ink=adaptive(0x242923,0xedf0e9),muted=adaptive(0x686f65,0xadb5a8),line=adaptive(0xdcded7,0x3a4039),soft=adaptive(0xe3e7de,0x394136),accent=adaptive(0x344b38,0xc4d2bf)
}
final class SampleImages {
  static let shared=SampleImages(); let images: [NSImage]
  init(){let source=NSImage(contentsOf:Bundle.main.url(forResource:"samples",withExtension:"jpg")!)!;let cg=source.cgImage(forProposedRect:nil,context:nil,hints:nil)!;images=(0..<9).map {i in let w=cg.width/3,h=cg.height/3;let crop=cg.cropping(to:CGRect(x:i%3*w,y:i/3*h,width:w,height:h))!;return NSImage(cgImage:crop,size:NSSize(width:w,height:h))}}
}
struct ToolButton: View {
  var title:String;var symbol:String;var enabled=true;var action:()->Void
  var body: some View { Button(action:action){Label(title,systemImage:symbol).font(.system(size:12)).padding(.horizontal,7).padding(.vertical,6).contentShape(Rectangle())}.buttonStyle(.plain).disabled(!enabled).opacity(enabled ? 1:0.35) }
}
