    .sheet(isPresented:$folderSheet){VStack(alignment:.leading,spacing:18){Text("Open a folder").font(.system(size:21,weight:.medium));Text("No import. Browse the files where they are.").foregroundStyle(Palette.muted);Button("Studio studies · Pictures"){model.setScenario("Browse");folderSheet=false};Button("Render box · /home/demo/outputs"){model.setScenario("Remote");folderSheet=false};HStack{Spacer();Button("Cancel"){folderSheet=false};Button("Choose folder…"){model.setScenario("Browse");folderSheet=false}.buttonStyle(.borderedProminent)}}.padding(28).frame(width:440)}
