@main struct WorkspaceDesign {
  static func main(){let app=NSApplication.shared;app.setActivationPolicy(.regular);let state=DesignState();let window=NSWindow(contentRect:NSRect(x:0,y:0,width:1280,height:800),styleMask:[.titled,.closable,.miniaturizable,.resizable],backing:.buffered,defer:false);window.title="Frame — Design prototype";window.titlebarAppearsTransparent=true;window.contentView=NSHostingView(rootView:NativeDesign(model:state));window.minSize=NSSize(width:960,height:640);window.center();let delegate=MenuActions(state:state,window:window);let menu=NSMenu();let appItem=NSMenuItem();menu.addItem(appItem);let appMenu=NSMenu();appMenu.addItem(withTitle:"Quit prototype",action:#selector(NSApplication.terminate(_:)),keyEquivalent:"q");appItem.submenu=appMenu;let design=NSMenuItem(title:"Prototype",action:nil,keyEquivalent:"");let designMenu=NSMenu();for label in ["Image-led","Grid-led","Light","Dark","Browse","Batch","Archive","Remote","First remote use","Start","1280 × 800","960 × 640"]{let item=NSMenuItem(title:label,action:#selector(MenuActions.choose(_:)),keyEquivalent:"");item.target=delegate;designMenu.addItem(item)};design.submenu=designMenu;menu.addItem(design);app.mainMenu=menu;window.makeKeyAndOrderFront(nil);withExtendedLifetime(delegate){app.run()}}
}
final class MenuActions:NSObject {let state:DesignState;let window:NSWindow;init(state:DesignState,window:NSWindow){self.state=state;self.window=window};@objc func choose(_ item:NSMenuItem){switch item.title {case "Image-led":state.grid=false;case "Grid-led":state.grid=true;case "Light":window.appearance=NSAppearance(named:.aqua);case "Dark":window.appearance=NSAppearance(named:.darkAqua);case "1280 × 800":window.setContentSize(NSSize(width:1280,height:800));case "960 × 640":window.setContentSize(NSSize(width:960,height:640));state.showRail=false;state.previewHeight=300;state.gridPreviewWidth=400;state.gridImageHeight=280;default:state.setScenario(item.title)}}}
